-- Rollback-only exercise of the same queue APIs used by the dashboard and worker.
begin;
do $$
declare uid uuid; sid uuid; c jsonb; a jsonb; p jsonb; photo jsonb; k text=repeat('c',64); cid uuid; real_slug text; denied boolean=false;
begin
 select u.id,s.id into uid,sid from auth.users u join auth.sessions s on s.user_id=u.id where u.email='akm@indiagully.com' limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'session_id',sid,'aal','aal2','role','authenticated')::text,true);
 update ig_private.integration_root set secret_hash=encode(extensions.digest(convert_to(k,'UTF8'),'sha256'),'hex');
 update ig_private.integration_config set mode='enabled',settings=settings||'{"daily_request_limit":20}' where id in ('openai','runway');
 c=public.ig_brand_catalogue(jsonb_build_object('action','prepare','approved',true,'name','Fixtures.pdf','size',1234,'brand','Queue fixtures','sha256',repeat('2',64),'rights_reference','Fixture source for this test'));
 cid=(c->>'id')::uuid;
 insert into storage.objects(bucket_id,name,metadata) values('ig-brand-catalogues',c->>'path','{"size":1234}');
 perform public.ig_catalogue_run(jsonb_build_object('action','queue','id',cid,'first',1,'last',2,'auto_images',true));
 perform set_config('request.jwt.claims','{}',true);
 begin perform public.ig_catalogue_background('wrong','{"action":"claim"}');exception when insufficient_privilege then denied=true;end;assert denied,'Invalid worker was accepted';
 a=public.ig_catalogue_background(k,'{"action":"claim"}');
 assert (a->>'page')::int=1,'First page not claimed';
 assert public.ig_catalogue_background(k,'{"action":"claim"}') is null,'Duplicate active page';
 a=jsonb_build_object('id',cid,'lease',a->'lease','ai_job',a->'ai_job');
 assert public.ig_catalogue_background(k,a||'{"action":"source"}')->>'path'=c->>'path','Unexpected source scope';
 photo=public.ig_catalogue_background(k,a||'{"action":"asset","item":0,"alt":"Supplier photograph"}');
 insert into storage.objects(bucket_id,name,metadata) values('ig-source-media',photo->>'path','{"size":2000}');
 assert public.ig_catalogue_background(k,a||'{"action":"asset","item":1,"original":0,"alt":"Supplier photograph"}')->>'path'=photo->>'path','Variants did not share imagery';
 p=jsonb_build_object('title','Queue fixture light','reference','fixture-a','uom','piece','category','Light','summary','Fixture light for testing','specifications','Fixture specification','evidence','Page 1','photo_source','product_crop','image_quality','enhance');
 p=jsonb_build_object('products',jsonb_build_array(p,p||'{"reference":"fixture-b"}'),'complete',true);
 perform public.ig_ai_finish(k,jsonb_build_object('id',a->'ai_job','status','ready','draft',p));
 perform public.ig_catalogue_background(k,a||jsonb_build_object('action','finish','result',p,'page_count',2));
 assert (select count(*)=2 from public.ig_content where public_data->>'brand'='Queue fixtures' and public_data->>'image' like '/images/library/%' and status='draft'),'Drafts and model images did not persist';
 assert not exists(select 1 from public.ig_public_content where public_data->>'brand'='Queue fixtures'),'A product was published without review';
 assert (select count(*)=2 from ig_private.catalogue_artwork where catalogue_id=cid),'Missing image follow-up jobs';
 perform public.ig_catalogue_next_artwork(k);perform public.ig_catalogue_next_artwork(k);
 assert (select count(*)=1 from public.ig_provider_jobs where input->>'product_title'='Queue fixture light'),'Variant enhancement not deduplicated';
 update ig_private.integration_config set settings=settings||'{"daily_request_limit":1}' where id='openai';
 update ig_private.catalogue_runs set due=now() where catalogue_id=cid;
 assert public.ig_catalogue_background(k,'{"action":"claim"}') is null,'Daily cap bypassed';
 assert (select state='waiting' and (due at time zone 'Asia/Kolkata')::time='00:00' from ig_private.catalogue_runs where catalogue_id=cid),'Reset was not scheduled at India midnight';
 -- A one-request allowance for page two must not apply to other pages or charge a retry.
 update public.ig_ai_jobs set created_at=now()-interval '2 minutes' where actor_id=uid;
 insert into ig_private.catalogue_request_allowances(catalogue_id,first_page,last_page,request_limit) values(cid,1,1,1);
 update ig_private.catalogue_runs set due=now() where catalogue_id=cid;
 assert public.ig_catalogue_background(k,'{"action":"claim"}') is null,'Page outside allowance was admitted';
 update ig_private.catalogue_request_allowances set first_page=2,last_page=2 where catalogue_id=cid;
 update ig_private.catalogue_runs set due=now() where catalogue_id=cid;
 a=public.ig_catalogue_background(k,'{"action":"claim"}');assert (a->>'page')::int=2,'Did not resume at next page';
 assert (select used=1 from ig_private.catalogue_request_allowances where catalogue_id=cid),'Allowance was not debited';
 assert (select catalogue_extra from public.ig_ai_jobs where id=(a->>'ai_job')::uuid),'Request charged to general budget';
 perform public.ig_ai_finish(k,jsonb_build_object('id',a->'ai_job','status','ready','draft','{"products":[],"complete":true}'::jsonb));
 perform public.ig_catalogue_background(k,a||'{"action":"fail","note":"Temporary storage failure"}');
 update ig_private.catalogue_runs set due=now() where catalogue_id=cid;
 a=public.ig_catalogue_background(k,'{"action":"claim"}');assert a->'cached'->'products'='[]','Paid extraction lost on retry';
 perform public.ig_catalogue_background(k,a||'{"action":"finish","page_count":2,"result":{"products":[],"complete":true}}');
 update ig_private.catalogue_runs set due=now() where catalogue_id=cid;
 assert public.ig_catalogue_background(k,'{"action":"claim"}') is null,'Completed import still issuing requests';
 assert (select used=1 and closed_at is not null from ig_private.catalogue_request_allowances where catalogue_id=cid),'Retry used an extra request or the completed allowance remained open';
 assert (select state='complete' from ig_private.catalogue_runs where catalogue_id=cid),'Import not marked complete';
end $$;
rollback;
